/**
 * Share-token handling.
 *
 * Two rules govern this file:
 *
 *   1. A token is a bearer credential. It is never stored in the database —
 *      only its SHA-256 hash is — and it is never logged in full.
 *   2. Every rejection is identical. Distinguishing "expired" from "revoked"
 *      from "never existed" turns the endpoint into a token oracle.
 */

/** Tokens are URL-safe, fixed-length, generated by the server. */
const TOKEN_PATTERN = /^[A-Za-z0-9_-]{22,128}$/;

export function isValidTokenFormat(token: string | null | undefined): token is string {
  return typeof token === 'string' && TOKEN_PATTERN.test(token);
}

/**
 * Reduces a token to something safe to write to a log.
 *
 * Logs are retained far longer than sessions and are read by more people than
 * the database is. Keeping only a short prefix lets an operator correlate an
 * incident without handing them a working share URL.
 */
export function redactToken(token: string | null | undefined): string {
  if (!token) return '(none)';
  if (token.length <= 8) return '(redacted)';
  return `${token.slice(0, 4)}…(${token.length})`;
}

/** Generates a token using the platform CSPRNG. */
export function generateToken(byteLength = 32): string {
  const bytes = new Uint8Array(byteLength);
  crypto.getRandomValues(bytes);
  // base64url, no padding — URL-safe and filesystem-safe.
  let binary = '';
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
